/**
 * HubSpot side of the firewall:
 *   - webhook authentication (HubSpot signature v3, or a shared-secret header for workflow webhooks),
 *   - event parsing (app webhook event arrays, or a single { objectType, objectId } body),
 *   - object resolution (deal -> companies/contacts, company, contact),
 *   - reconciliation search, and the guarded DNC back-sync write.
 *
 * Writes honour DRY_RUN and SANDBOX_MODE (sandbox / developer-test portal only).
 * A placeholder token puts the client offline: reads use injected fixtures, writes are refused.
 */

class CrmGuardError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'CrmGuardError';
    this.code = code;
  }
}

function headerOf(headers, name) {
  for (const [k, v] of Object.entries(headers || {})) if (k.toLowerCase() === name.toLowerCase()) return Array.isArray(v) ? v[0] : v;
  return null;
}

function constantTimeEqual(a, b) {
  const x = Buffer.from(String(a || ''));
  const y = Buffer.from(String(b || ''));
  return x.length === y.length && x.length > 0 && crypto.timingSafeEqual(x, y);
}

/** HubSpot v3: base64(HMAC-SHA256(clientSecret, method + uri + body + timestamp)); timestamp within maxAge. */
function computeHubSpotV3Signature({ secret, method, uri, rawBody, timestamp }) {
  return crypto.createHmac('sha256', String(secret)).update(`${method.toUpperCase()}${uri}${rawBody}${timestamp}`, 'utf8').digest('base64');
}

function authenticateCrmWebhook({ rawBody, headers, method = 'POST', webhookConfig, now = Date.now() }) {
  if (isPlaceholderSecret(webhookConfig.signingSecret)) return { valid: true, reason: 'unauthenticated_dry_run' };
  if (webhookConfig.authMode === 'shared_secret') {
    return constantTimeEqual(headerOf(headers, webhookConfig.sharedSecretHeader), webhookConfig.signingSecret)
      ? { valid: true, reason: 'shared_secret' }
      : { valid: false, reason: 'shared_secret_mismatch' };
  }
  const signature = headerOf(headers, 'x-hubspot-signature-v3');
  const timestamp = headerOf(headers, 'x-hubspot-request-timestamp');
  if (!signature || !timestamp) return { valid: false, reason: 'signature_headers_missing' };
  if (!/^\d{10,13}$/.test(String(timestamp)) || Math.abs(now - Number(timestamp)) > webhookConfig.maxAgeSeconds * 1000) {
    return { valid: false, reason: 'timestamp_outside_window' };
  }
  const expected = computeHubSpotV3Signature({ secret: webhookConfig.signingSecret, method, uri: webhookConfig.publicUrl, rawBody, timestamp });
  return constantTimeEqual(signature, expected) ? { valid: true, reason: 'hubspot_v3' } : { valid: false, reason: 'signature_mismatch' };
}

const OBJECT_TYPES = { deal: 'deal', deals: 'deal', company: 'company', companies: 'company', contact: 'contact', contacts: 'contact', '0-3': 'deal', '0-2': 'company', '0-1': 'contact' };

/** Normalizes HubSpot payloads into [{ objectType, objectId, trigger }], de-duplicated. */
function parseCrmEvents(payload, query = {}) {
  const list = Array.isArray(payload) ? payload : [payload];
  const events = [];
  for (const e of list) {
    if (!e || typeof e !== 'object') continue;
    const fromSubscription = e.subscriptionType ? String(e.subscriptionType).split('.')[0] : null;
    const type = OBJECT_TYPES[String(e.objectType || e.objectTypeId || fromSubscription || query.objectType || '').toLowerCase()];
    const idRaw = e.objectId ?? e.hs_object_id ?? (e.properties && e.properties.hs_object_id && (e.properties.hs_object_id.value ?? e.properties.hs_object_id));
    const id = idRaw !== undefined && /^\d{1,20}$/.test(String(idRaw)) ? String(idRaw) : null;
    if (!type || !id) continue;
    events.push({ objectType: type, objectId: id, trigger: e.subscriptionType ? `${e.subscriptionType}${e.propertyName ? `:${e.propertyName}` : ''}` : 'workflow_webhook' });
  }
  const seen = new Set();
  return events.filter((e) => {
    const key = `${e.objectType}:${e.objectId}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const DEAL_PROPERTIES = ['dealname', 'dealstage', 'pipeline', 'hs_is_closed', 'hs_is_closed_won', 'hs_lastmodifieddate'];
const COMPANY_PROPERTIES = ['name', 'domain', 'hs_additional_domains', 'lifecyclestage', 'type'];
const CONTACT_PROPERTIES = ['email', 'lifecyclestage', 'hs_email_optout', 'outbound_do_not_contact'];

function createCrmClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((r) => setTimeout(r, ms)),
  offline: offlineData = {},
}) {
  const offline = isPlaceholderSecret(token);
  const api = String(baseUrl).replace(/\/+$/, '');
  let sandboxCheck = null;

  async function call(method, path, body, { allow404 = false } = {}) {
    if (offline) throw new CrmGuardError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${api}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if (response.status === 404 && allow404) return null;
      if ((response.status === 429 || response.status >= 500) && attempt < 3) {
        await sleep(Math.min(1000 * 2 ** attempt, 8000));
        continue;
      }
      const text = await response.text();
      if (!response.ok) throw new CrmGuardError(`http_${response.status}`, `HubSpot ${method} ${path.split('?')[0]} failed with HTTP ${response.status}`);
      return text ? JSON.parse(text) : {};
    }
  }

  async function batchRead(objectType, ids, properties) {
    if (!ids.length) return [];
    const r = await call('POST', `/crm/v3/objects/${objectType}/batch/read`, { properties, inputs: ids.slice(0, 100).map((id) => ({ id })) });
    return ((r && r.results) || []).map((o) => ({ id: String(o.id), ...o.properties }));
  }

  async function getWithAssociations(objectType, id, properties, associations) {
    const assoc = associations.length ? `&associations=${associations.join(',')}` : '';
    const r = await call('GET', `/crm/v3/objects/${objectType}/${encodeURIComponent(id)}?properties=${properties.join(',')}${assoc}`, undefined, { allow404: true });
    if (!r) return null;
    const ids = (type) => ((r.associations && r.associations[type] && r.associations[type].results) || []).map((x) => String(x.id));
    return { id: String(r.id), properties: r.properties || {}, companyIds: ids('companies'), contactIds: ids('contacts') };
  }

  /** Returns { deal?, company?, contact?, companies, contacts } for one event. */
  async function resolveEvent(event, { maxContacts = 50 } = {}) {
    if (offline) {
      const key = `${event.objectType}:${event.objectId}`;
      return offlineData[key] || null;
    }
    if (event.objectType === 'deal') {
      const deal = await getWithAssociations('deals', event.objectId, DEAL_PROPERTIES, ['companies', 'contacts']);
      if (!deal) return null;
      return {
        deal: { id: deal.id, ...deal.properties },
        companies: await batchRead('companies', deal.companyIds, COMPANY_PROPERTIES),
        contacts: await batchRead('contacts', deal.contactIds.slice(0, maxContacts), CONTACT_PROPERTIES),
      };
    }
    if (event.objectType === 'company') {
      const company = await getWithAssociations('companies', event.objectId, COMPANY_PROPERTIES, []);
      return company ? { company: { id: company.id, ...company.properties }, companies: [{ id: company.id, ...company.properties }], contacts: [] } : null;
    }
    const contact = await getWithAssociations('contacts', event.objectId, CONTACT_PROPERTIES, []);
    return contact ? { contact: { id: contact.id, ...contact.properties }, companies: [], contacts: [{ id: contact.id, ...contact.properties }] } : null;
  }

  /** Deals modified since `sinceMs` that are closed-won or still open. */
  async function searchRecentDeals({ sinceMs, maxDeals }) {
    if (offline) return (offlineData.recentDeals || []).slice(0, maxDeals);
    const ids = [];
    let after;
    do {
      const body = {
        filterGroups: [{ filters: [{ propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: String(sinceMs) }] }],
        properties: DEAL_PROPERTIES,
        limit: 100,
        sorts: [{ propertyName: 'hs_lastmodifieddate', direction: 'ASCENDING' }],
      };
      if (after) body.after = after;
      const page = await call('POST', '/crm/v3/objects/deals/search', body);
      for (const d of (page && page.results) || []) ids.push(String(d.id));
      after = page && page.paging && page.paging.next ? page.paging.next.after : undefined;
      if (after) await sleep(250);
    } while (after && ids.length < maxDeals);
    return ids.slice(0, maxDeals).map((id) => ({ objectType: 'deal', objectId: id, trigger: 'reconciliation' }));
  }

  async function verifySandbox() {
    if (!sandboxCheck) {
      sandboxCheck = (async () => {
        const d = await call('GET', '/account-info/v3/details');
        const portalId = String(d && d.portalId !== undefined ? d.portalId : '');
        const accountType = String((d && d.accountType) || '').toUpperCase();
        if (!isPlaceholderSecret(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) throw new CrmGuardError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token is not for HUBSPOT_SANDBOX_PORTAL_ID');
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new CrmGuardError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return true;
      })();
    }
    return sandboxCheck;
  }

  /** Back-sync: flag a contact (found by email) as do-not-contact for outbound. */
  async function flagContactDnc({ email, dncProperty, source, nowIso }) {
    if (dryRun) return { mode: 'intercepted_dry_run', property: dncProperty };
    if (offline) throw new CrmGuardError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    if (sandboxMode) await verifySandbox();
    const found = await call('POST', '/crm/v3/objects/contacts/search', {
      filterGroups: [{ filters: [{ propertyName: 'email', operator: 'EQ', value: email }] }],
      properties: ['email'],
      limit: 1,
    });
    const contact = found && found.results && found.results[0];
    if (!contact) return { mode: 'contact_not_found' };
    await call('PATCH', `/crm/v3/objects/contacts/${encodeURIComponent(contact.id)}`, {
      properties: { [dncProperty]: 'true', outbound_dnc_source: source, outbound_dnc_at: nowIso },
    });
    return { mode: 'written', contactId: String(contact.id) };
  }

  return { offline, resolveEvent, searchRecentDeals, flagContactDnc, verifySandbox };
}

// ---- src/core/sequencers.js ----
/**
 * Smartlead and Instantly global blocklist requests.
 *
 *   Smartlead  POST {SMARTLEAD_BASE_URL}/leads/add-domain-block-list?api_key=...
 *              body { "domain_block_list": ["acme.example", "person@freemail.example"], "client_id"?: ... }
 *   Instantly  POST {INSTANTLY_BASE_URL}/block-lists-entries/bulk-create
 *              Authorization: Bearer ...   body { "bl_values": [...] }
 *
 * buildSequencerBatches() is shared by both runtimes: in n8n the batches feed HTTP Request
 * nodes (keys come from $env there); in Node.js executeSequencerBatch() sends them the same way.
 * Keys never appear in batch items.
 */

const SEQUENCER_NAMES = ['smartlead', 'instantly'];

function buildSequencerBatches(entries, config) {
  const batches = [];
  for (const name of SEQUENCER_NAMES) {
    const s = config.sequencers[name];
    if (!s.enabled) continue;
    const values = [...new Set(entries.filter((e) => !(e.excludeSequencers || []).includes(name)).map((e) => e.value))];
    const keyMissing = isPlaceholderSecret(sequencerKey(config, name));
    for (let i = 0; i < values.length; i += config.sequencers.batchSize) {
      const chunk = values.slice(i, i + config.sequencers.batchSize);
      const categories = [...new Set(entries.filter((e) => chunk.includes(e.value)).flatMap((e) => e.categories || [e.category]))];
      const body = name === 'smartlead' ? { domain_block_list: chunk } : { bl_values: chunk };
      if (name === 'smartlead' && !isPlaceholderSecret(s.clientId)) body.client_id = /^\d+$/.test(s.clientId) ? Number(s.clientId) : s.clientId;
      batches.push({
        sequencer: name,
        mode: config.dryRun ? 'dry_run' : keyMissing ? 'blocked' : 'live',
        blockedReason: !config.dryRun && keyMissing ? `${name} ${config.sandboxMode ? 'sandbox ' : ''}API key missing` : null,
        sandbox: config.sandboxMode,
        method: 'POST',
        url: name === 'smartlead' ? `${s.baseUrl.replace(/\/+$/, '')}/leads/add-domain-block-list` : `${s.baseUrl.replace(/\/+$/, '')}/block-lists-entries/bulk-create`,
        body,
        count: chunk.length,
        categories,
        preview: chunk.slice(0, 5).map(maskValue),
      });
    }
  }
  return batches;
}

/** Node.js equivalent of the two n8n HTTP Request nodes. */
async function executeSequencerBatch(batch, { config, fetchImpl, sleep = (ms) => new Promise((r) => setTimeout(r, ms)) }) {
  if (batch.mode !== 'live') return { sequencer: batch.sequencer, mode: batch.mode, count: batch.count, reason: batch.blockedReason };
  const key = sequencerKey(config, batch.sequencer);
  const url = batch.sequencer === 'smartlead' ? `${batch.url}?api_key=${encodeURIComponent(key)}` : batch.url;
  const headers = { 'content-type': 'application/json' };
  if (batch.sequencer === 'instantly') headers.authorization = `Bearer ${key}`;
  for (let attempt = 0; ; attempt += 1) {
    const response = await fetchImpl(url, { method: 'POST', headers, body: JSON.stringify(batch.body) });
    if ((response.status === 429 || response.status >= 500) && attempt < 2) {
      await sleep(2000 * (attempt + 1));
      continue;
    }
    const text = await response.text();
    if (!response.ok) {
      const err = new Error(`${batch.sequencer} blocklist push failed with HTTP ${response.status}`);
      err.code = `${batch.sequencer}_http_${response.status}`;
      throw err;
    }
    return { sequencer: batch.sequencer, mode: 'pushed', count: batch.count, status: response.status, sandbox: batch.sandbox, responseBytes: text.length };
  }
}

// ---- src/core/pipeline.js ----
/**
 * Stages shared by the Node.js runtime and the n8n workflow.
 *
 *   CRM -> sequencers  crmIngest -> crmResolve (router) -> buildBatches -> push
 *   Sequencer -> CRM   optOutIngest -> optOutBackSync -> buildBatches (cross-sequencer) -> push
 *   Reconciliation     reconcileCollect -> crmResolve -> buildBatches -> push
 *
 * Router rules (crmResolve):
 *   deal closed-won            -> "customer"   company domains (+ free-mail contact emails)
 *   deal open                  -> "open_deal"  company domains (+ free-mail contact emails)
 *   deal closed-lost           -> nothing pushed; reported as a release candidate (never auto-removed)
 *   company type = competitor  -> "competitor" company domains; COMPETITOR_DOMAINS always included in reconciliation
 *   company/contact customer   -> "customer"
 *   contact DNC / opt-out      -> "dnc"        contact email
 */

function createSuppressionClients(config, { fetchImpl, sleep, offline } = {}) {
  return {
    crm: createCrmClient({
      token: config.hubspot.token,
      dryRun: config.dryRun,
      sandboxMode: config.sandboxMode,
      sandboxPortalId: config.hubspot.sandboxPortalId,
      baseUrl: config.hubspot.baseUrl,
      fetchImpl,
      ...(sleep ? { sleep } : {}),
      ...(offline ? { offline } : {}),
    }),
  };
}

const truthy = (v) => String(v).toLowerCase() === 'true';

function crmIngestStage({ rawBody, headers = {}, query = {}, method = 'POST' }, { config, now = Date.now() }) {
  const base = { flow: 'crm', receivedAt: new Date(now).toISOString(), dryRun: config.dryRun, sandboxMode: config.sandboxMode };
  const { errors, warnings } = validateSuppressionConfig(config);
  if (errors.length) return { ...base, status: 'rejected', httpStatus: 500, reason: 'config_invalid', errors };
  const raw = typeof rawBody === 'string' ? rawBody : '';
  if (Buffer.byteLength(raw, 'utf8') > config.webhook.maxBodyBytes) return { ...base, status: 'rejected', httpStatus: 413, reason: 'payload_too_large' };
  const auth = authenticateCrmWebhook({ rawBody: raw, headers, method, webhookConfig: config.webhook, now });
  if (!auth.valid) return { ...base, status: 'rejected', httpStatus: 401, reason: auth.reason };
  let payload;
  try {
    payload = JSON.parse(raw || 'null');
  } catch {
    return { ...base, status: 'rejected', httpStatus: 400, reason: 'invalid_json' };
  }
  const events = parseCrmEvents(payload, query);
  if (!events.length) return { ...base, status: 'ignored', httpStatus: 200, reason: 'no_supported_events', warnings };
  return { ...base, status: 'accepted', httpStatus: 200, reason: auth.reason, events, warnings };
}

/** The router: maps one resolved HubSpot object to suppression entries. */
function classifyResolved(event, resolved, config) {
  const rules = config.rules;
  const out = { entries: [], skipped: [], notes: [] };
  const add = (result) => {
    out.entries.push(...result.entries);
    out.skipped.push(...result.skipped);
  };
  if (!resolved) {
    out.notes.push(`${event.objectType}:${event.objectId} not found`);
    return out;
  }
  const source = `${event.objectType}:${event.objectId}`;
  if (resolved.deal) {
    const d = resolved.deal;
    if (truthy(d.hs_is_closed_won)) {
      if (rules.closedWon) add(entriesForCompanyAndContacts({ companies: resolved.companies, contacts: resolved.contacts, category: 'customer', reason: 'closed-won deal', source, rules }));
    } else if (truthy(d.hs_is_closed)) {
      out.notes.push(`closed-lost deal ${d.id}: release candidate (blocklist entries are never removed automatically)`);
    } else if (rules.openDeals && (!rules.openDealPipelines.length || rules.openDealPipelines.includes(String(d.pipeline)))) {
      add(entriesForCompanyAndContacts({ companies: resolved.companies, contacts: resolved.contacts, category: 'open_deal', reason: 'open deal', source, rules }));
    }
  }
  if (resolved.company) {
    const c = resolved.company;
    const domain = normalizeDomain(c.domain);
    const competitorValue = String(c[rules.competitorProperty] || '').toLowerCase();
    if (rules.competitors && (rules.competitorValues.includes(competitorValue) || (domain && rules.competitorDomains.includes(domain)))) {
      add(entriesForCompanyAndContacts({ companies: [c], category: 'competitor', reason: 'competitor company', source, rules }));
    }
    if (rules.customerLifecycle && String(c.lifecyclestage).toLowerCase() === 'customer') {
      add(entriesForCompanyAndContacts({ companies: [c], category: 'customer', reason: 'customer lifecycle stage', source, rules }));
    }
  }
  if (resolved.contact) {
    const p = resolved.contact;
    if (rules.dnc && rules.dncProperties.some((prop) => truthy(p[prop]))) add(emailEntry({ email: p.email, category: 'dnc', reason: 'do-not-contact / opt-out', source, rules }));
    if (rules.customerLifecycle && String(p.lifecyclestage).toLowerCase() === 'customer') add(emailEntry({ email: p.email, category: 'customer', reason: 'customer contact', source, rules }));
  }
  return out;
}

async function crmResolveStage(ctx, { config, crm }) {
  if (ctx.status !== 'accepted') return ctx;
  const entries = [...(ctx.seedEntries || [])];
  const skipped = [];
  const notes = [];
  for (const event of ctx.events) {
    const resolved = await crm.resolveEvent(event, { maxContacts: config.hubspot.maxContactsPerDeal });
    const r = classifyResolved(event, resolved, config);
    entries.push(...r.entries);
    skipped.push(...r.skipped);
    notes.push(...r.notes);
  }
  const deduped = dedupeEntries(entries);
  const byCategory = Object.fromEntries(SUPPRESSION_CATEGORIES.map((c) => [c, deduped.filter((e) => e.categories.includes(c)).length]));
  return { ...ctx, status: 'resolved', entries: deduped, skipped, notes, byCategory };
}

function parseSequencerOptOut({ body = {}, query = {}, headers = {} }, config) {
  const headerToken = Object.entries(headers || {}).find(([k]) => k.toLowerCase() === 'x-sequencer-secret');
  const token = query.token || (headerToken ? headerToken[1] : '') || '';
  const secret = config.webhook.sequencerSecret;
  const authOk = isPlaceholderSecret(secret) ? config.dryRun : constantTimeEqual(token, secret);
  if (!authOk) return { valid: false, reason: 'sequencer_secret_mismatch' };
  const source = ['smartlead', 'instantly'].includes(String(query.source).toLowerCase()) ? String(query.source).toLowerCase() : body.campaign_id && body.sl_email_lead_id ? 'smartlead' : 'unknown';
  const eventType = String(body.event_type || body.event || body.type || '').toLowerCase();
  if (!config.backSync.optOutEvents.includes(eventType)) return { valid: true, ignored: true, reason: `event_not_tracked:${eventType || 'none'}`, source };
  const candidates = [body.lead_email, body.to_email, body.sl_lead_email, body.email, body.lead && body.lead.email, body.data && body.data.email];
  const email = candidates.map(normalizeEmailValue).find(Boolean) || null;
  if (!email) return { valid: true, ignored: true, reason: 'no_email_in_payload', source };
  return { valid: true, ignored: false, source, eventType, email };
}

function optOutIngestStage(input, { config, now = Date.now() }) {
  const base = { flow: 'sequencer_opt_out', receivedAt: new Date(now).toISOString(), dryRun: config.dryRun, sandboxMode: config.sandboxMode };
  const { errors } = validateSuppressionConfig(config);
  if (errors.length) return { ...base, status: 'rejected', httpStatus: 500, reason: 'config_invalid', errors };
  const parsed = parseSequencerOptOut(input, config);
  if (!parsed.valid) return { ...base, status: 'rejected', httpStatus: 401, reason: parsed.reason };
  if (parsed.ignored) return { ...base, status: 'ignored', httpStatus: 200, reason: parsed.reason, source: parsed.source };
  return { ...base, status: 'accepted', httpStatus: 200, source: parsed.source, eventType: parsed.eventType, email: parsed.email };
}

async function optOutBackSyncStage(ctx, { config, crm, now = Date.now() }) {
  if (ctx.status !== 'accepted') return ctx;
  let hubspot = { mode: 'disabled' };
  if (config.backSync.toHubSpot) {
    try {
      hubspot = await crm.flagContactDnc({ email: ctx.email, dncProperty: config.hubspot.dncProperty, source: ctx.source, nowIso: new Date(now).toISOString() });
    } catch (err) {
      hubspot = { mode: 'error', code: err.code || null };
    }
  }
  const { entries } = emailEntry({ email: ctx.email, category: 'dnc', reason: `opt-out reported by ${ctx.source}`, source: `sequencer:${ctx.source}`, rules: config.rules });
  const crossEntries = config.backSync.crossSequencer
    ? dedupeEntries(entries).map((e) => ({ ...e, excludeSequencers: ctx.source === 'unknown' ? [] : [ctx.source] }))
    : [];
  const { email, ...rest } = ctx;
  return { ...rest, status: 'resolved', hubspot, entries: crossEntries, byCategory: { dnc: crossEntries.length } };
}

async function reconcileCollectStage({ config, crm, now = Date.now() }) {
  const base = { flow: 'reconciliation', receivedAt: new Date(now).toISOString(), dryRun: config.dryRun, sandboxMode: config.sandboxMode };
  const { errors } = validateSuppressionConfig(config);
  if (errors.length) return { ...base, status: 'rejected', reason: 'config_invalid', errors };
  const sinceMs = now - config.reconcile.lookbackHours * 3600 * 1000;
  const events = await crm.searchRecentDeals({ sinceMs, maxDeals: config.reconcile.maxDeals });
  const seedEntries = config.rules.competitors
    ? config.rules.competitorDomains.map(normalizeDomain).filter(Boolean).map((value) => ({ value, kind: 'domain', category: 'competitor', reason: 'COMPETITOR_DOMAINS', source: 'config' }))
    : [];
  return { ...base, status: 'accepted', events, seedEntries, since: new Date(sinceMs).toISOString() };
}

function buildBatchesStage(ctx, { config }) {
  if (ctx.status !== 'resolved') return { ...ctx, batches: [] };
  return { ...ctx, batches: buildSequencerBatches(ctx.entries, config) };
}

function summarizeRun(ctx, results = []) {
  return {
    flow: ctx.flow,
    status: ctx.status === 'resolved' ? 'processed' : ctx.status,
    reason: ctx.reason || null,
    dryRun: ctx.dryRun,
    sandboxMode: ctx.sandboxMode,
    events: ctx.events ? ctx.events.length : undefined,
    entries: ctx.entries ? ctx.entries.length : 0,
    byCategory: ctx.byCategory || {},
    skipped: ctx.skipped ? ctx.skipped.length : 0,
    notes: ctx.notes || [],
    hubspotBackSync: ctx.hubspot || undefined,
    batches: (ctx.batches || []).map((b) => ({ sequencer: b.sequencer, mode: b.mode, count: b.count, categories: b.categories })),
    pushes: results,
    errors: ctx.errors || [],
  };
}

/** Node.js mirror: run batches like the n8n HTTP Request nodes would. Failures are reported per batch. */
async function pushBatches(batches, { config, fetchImpl, sleep }) {
  const results = [];
  for (const batch of batches) {
    try {
      results.push(await executeSequencerBatch(batch, { config, fetchImpl, ...(sleep ? { sleep } : {}) }));
    } catch (err) {
      results.push({ sequencer: batch.sequencer, mode: 'failed', count: batch.count, code: err.code || null });
    }
  }
  return results;
}

async function handleCrmWebhook(input, { config, fetchImpl = globalThis.fetch, clients, sleep, now = () => Date.now() }) {
  const { crm } = clients || createSuppressionClients(config, { fetchImpl, sleep });
  let ctx = crmIngestStage(input, { config, now: now() });
  ctx = await crmResolveStage(ctx, { config, crm });
  ctx = buildBatchesStage(ctx, { config });
  const results = await pushBatches(ctx.batches, { config, fetchImpl, sleep });
  return { httpStatus: ctx.httpStatus || 200, summary: summarizeRun(ctx, results), batches: ctx.batches };
}

async function handleSequencerOptOut(input, { config, fetchImpl = globalThis.fetch, clients, sleep, now = () => Date.now() }) {
  const { crm } = clients || createSuppressionClients(config, { fetchImpl, sleep });
  let ctx = optOutIngestStage(input, { config, now: now() });
  ctx = await optOutBackSyncStage(ctx, { config, crm, now: now() });
  ctx = buildBatchesStage(ctx, { config });
  const results = await pushBatches(ctx.batches, { config, fetchImpl, sleep });
  return { httpStatus: ctx.httpStatus || 200, summary: summarizeRun(ctx, results), batches: ctx.batches };
}

async function runReconciliation({ config, fetchImpl = globalThis.fetch, clients, sleep, now = () => Date.now() }) {
  const { crm } = clients || createSuppressionClients(config, { fetchImpl, sleep });
  let ctx = await reconcileCollectStage({ config, crm, now: now() });
  ctx = await crmResolveStage(ctx, { config, crm });
  ctx = buildBatchesStage(ctx, { config });
  const results = await pushBatches(ctx.batches, { config, fetchImpl, sleep });
  return { summary: summarizeRun(ctx, results), batches: ctx.batches };
}

async function postRunLog(summary, { config, fetchImpl }) {
  const url = config.log.webhookUrl;
  if (!/^https:\/\//.test(String(url || ''))) return { mode: 'not_configured' };
